import{H as e,V as t,et as n,j as r}from"./chunks/framework.DKIRGhFK.js";var i=JSON.parse(`{"title":"初识 Node.js","description":"","frontmatter":{},"headers":[],"relativePath":"nodejs/introduction.md","filePath":"nodejs/introduction.md"}`),a={name:`nodejs/introduction.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e(`<h1 id="初识-node-js" tabindex="-1">初识 Node.js <a class="header-anchor" href="#初识-node-js" aria-label="Permalink to “初识 Node.js”">​</a></h1><h2 id="什么是node-js" tabindex="-1">什么是Node.js <a class="header-anchor" href="#什么是node-js" aria-label="Permalink to “什么是Node.js”">​</a></h2><ul><li><p>Node.js® is a JavaScript runtime built on Chrome&#39;s V8 JavaScript engine.</p></li><li><p>Node.js 是一个基于Chrome V8 引擎的JavaScript 运行环境。</p></li></ul><p><a href="https://nodejs.org/zh-cn/" target="_blank" rel="noreferrer">Node.js 的官网地址</a></p><h2 id="node-js-中的javascript-运行环境" tabindex="-1">Node.js 中的JavaScript 运行环境 <a class="header-anchor" href="#node-js-中的javascript-运行环境" aria-label="Permalink to “Node.js 中的JavaScript 运行环境”">​</a></h2><ul><li><p>浏览器是 JavaScript 的前端运行环境。</p></li><li><p>Node.js 是 JavaScript 的后端运行环境。</p></li><li><p>Node.js 中无法调用 DOM 和 BOM 等浏览器内置 API。</p></li></ul><h2 id="node-js-可以做什么" tabindex="-1">Node.js 可以做什么 <a class="header-anchor" href="#node-js-可以做什么" aria-label="Permalink to “Node.js 可以做什么”">​</a></h2><p>Node.js 作为一个 JavaScript 的运行环境，仅仅提供了基础的功能和 API。然而，基于 Node.js 提供的这些基础能，很多强大</p><p>的工具和框架如雨后春笋，层出不穷，所以学会了 Node.js ，可以让前端程序员胜任更多的工作和岗位：</p><ul><li><p>基于 <a href="http://www.expressjs.com.cn/" target="_blank" rel="noreferrer">Express 框架</a>，可以快速构建 Web 应用</p></li><li><p>基于 <a href="https://electronjs.org/" target="_blank" rel="noreferrer">Electron 框架</a>，可以构建跨平台的桌面应用</p></li><li><p>基于 <a href="http://restify.com/" target="_blank" rel="noreferrer">restify 框架</a>，可以快速构建 API 接口项目</p></li><li><p>读写和操作数据库、创建实用的命令行工具辅助前端开发、etc…</p></li></ul><h2 id="node-js-怎么学" tabindex="-1">Node.js 怎么学 <a class="header-anchor" href="#node-js-怎么学" aria-label="Permalink to “Node.js 怎么学”">​</a></h2><ol><li>浏览器中的 JavaScript 学习路径：</li></ol><ul><li>JavaScript 基础语法 + 浏览器内置 API（DOM + BOM） + 第三方库（jQuery、art-template 等）</li></ul><ol start="2"><li>Node.js 的学习路径：</li></ol><ul><li>JavaScript 基础语法 + Node.js 内置 API 模块（fs、path、http等）+ 第三方 API 模块（express、mysql 等）</li></ul>`,15)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};